function getSingleItem(inp) {
  if (!inp) return {};
  if (Array.isArray(inp)) return getSingleItem(inp[0]);
  if (inp.items && Array.isArray(inp.items)) return getSingleItem(inp.items[0]);
  if (inp.json) return getSingleItem(inp.json);
  return inp;
}
const item = getSingleItem(input);
const body = item.body || item || {};
const action = (item.action || body.action || '').toLowerCase().trim();
if (!action.startsWith('feedback/')) return { json: { ignored: true } };

return {
  json: {
    success: true,
    action,
    data: { feedbackId: 'fb_' + Date.now(), received: true, timestamp: new Date().toISOString() }
  }
};

// 22. RESPONSE FORMATTER
const flatItems = [];

function collect(obj) {
  if (!obj) return;
  if (Array.isArray(obj)) {
    obj.forEach(collect);
  } else if (obj.items && Array.isArray(obj.items)) {
    obj.items.forEach(collect);
  } else if (obj.json) {
    collect(obj.json);
  } else if (typeof obj === 'object') {
    flatItems.push(obj);
  }
}

collect(input);

const validItems = flatItems.filter(it => !it.ignored);

// 1. Check Auth actions
const authItem = validItems.find(it => 
  (it.action && (it.action.startsWith('auth/') || it.action.includes('login') || it.action.includes('register') || it.action.includes('signup'))) ||
  (it.user && it.token)
);

if (authItem) {
  const user = authItem.user || authItem.data?.user;
  const token = authItem.token || authItem.data?.token;
  return {
    json: {
      success: authItem.success !== false,
      authenticated: true,
      action: authItem.action || 'auth/login',
      token: token || null,
      userId: user?.id || user?.userId || null,
      user: user || null,
      data: {
        user: user || null,
        token: token || null,
        ...(user || {})
      },
      error: authItem.error || null,
      message: authItem.message || null
    }
  };
}

// 2. Check properties/list action FIRST if action is properties/list or properties array exists
const isPropListRequest = validItems.some(it => it.action === 'properties/list' || it.action === 'properties');
if (isPropListRequest) {
  const propItem = validItems.find(it => it.properties && Array.isArray(it.properties));
  const props = propItem?.properties || propItem?.data?.properties || [];
  return {
    json: {
      success: true,
      action: 'properties/list',
      properties: props,
      count: props.length,
      data: {
        properties: props,
        total: props.length
      }
    }
  };
}

// 3. Check Matching result (matching/buyer)
const matchingItem = validItems.find(it => it.action === 'matching/buyer' && (it.recommendations || it.matches || it.data?.recommendations));
if (matchingItem) {
  const recs = matchingItem.recommendations || matchingItem.matches || matchingItem.data?.recommendations || [];
  return {
    json: {
      success: true,
      action: 'matching/buyer',
      recommendations: recs,
      matches: recs,
      data: {
        recommendations: recs,
        totalMatches: recs.length,
        evaluatedAt: new Date().toISOString()
      }
    }
  };
}

// 4. Any properties array
const anyPropsItem = validItems.find(it => it.properties && Array.isArray(it.properties));
if (anyPropsItem) {
  const props = anyPropsItem.properties || anyPropsItem.data?.properties || [];
  return {
    json: {
      success: true,
      action: 'properties/list',
      properties: props,
      count: props.length,
      data: {
        properties: props,
        total: props.length
      }
    }
  };
}

// 5. Any matching fallback
const anyMatching = validItems.find(it => it.recommendations || it.matches || it.action === 'matching/buyer');
if (anyMatching) {
  const recs = anyMatching.recommendations || anyMatching.matches || anyMatching.data?.recommendations || [];
  return {
    json: {
      success: true,
      action: 'matching/buyer',
      recommendations: recs,
      matches: recs,
      data: {
        recommendations: recs,
        totalMatches: recs.length,
        evaluatedAt: new Date().toISOString()
      }
    }
  };
}

// 6. Error item
const errorItem = validItems.find(it => it.error || it.success === false);
if (errorItem) {
  return {
    json: {
      success: false,
      action: errorItem.action || 'error',
      data: null,
      error: errorItem.error || { message: 'Processing failed' }
    }
  };
}

// 7. General item
const resultItem = validItems.find(it => it.data || it.properties || it.action);
if (resultItem) {
  return {
    json: {
      success: resultItem.success !== false,
      action: resultItem.action || 'success',
      data: resultItem.data !== undefined ? resultItem.data : resultItem
    }
  };
}

return {
  json: {
    success: true,
    data: validItems[0] || {}
  }
};

// 11. RANKING ENGINE
function getSingleItem(inp) {
  if (!inp) return {};
  if (Array.isArray(inp)) return getSingleItem(inp[0]);
  if (inp.items && Array.isArray(inp.items)) return getSingleItem(inp.items[0]);
  if (inp.json) return getSingleItem(inp.json);
  return inp;
}

const item = getSingleItem(input);
if (item.ignored || item.action === 'properties/list' || item.action === 'properties') {
  return { json: { ignored: true } };
}

const scored = Array.isArray(item.scoredProperties) 
  ? item.scoredProperties.slice() 
  : [];

scored.sort((a, b) => {
  const scoreA = Number(a.matchScore || 0);
  const scoreB = Number(b.matchScore || 0);
  if (scoreB !== scoreA) {
    return scoreB - scoreA;
  }
  return Number(a.price || 0) - Number(b.price || 0);
});

return {
  json: {
    ...item,
    scoredProperties: scored,
    rankedProperties: scored.slice(0, 10),
    totalRanked: scored.length
  }
};
